SourceCode.Declaration:
/// <summary>
/// How long Mobile ops records are kept (Mobile clean-up, Setup) - one row for the environment.
/// The D365FO days are applied by the daily HSMobileOpsCleanupBatch; the handheld days go to every
/// device with each HSMobileOpsDeviceWorkSvc answer. 0 days means never.
/// </summary>
public class HSMobileOpsCleanupSetup extends common
{
}

Method.Source:
/// <summary>
/// The clean-up settings. With no row yet, the defaults are returned without being written.
/// </summary>
public static HSMobileOpsCleanupSetup find(boolean _forUpdate = false)
{
    HSMobileOpsCleanupSetup setup;

    setup.selectForUpdate(_forUpdate);
    select firstOnly setup;
    if (!setup.RecId)
    {
        setup.Enabled       = NoYes::Yes;
        setup.DeviceCleanup = NoYes::Yes;
        setup.PostQueueRegisteredDays = 90;
        setup.PostQueueFailedDays = 180;
        setup.SignInLogDays = 90;
        setup.FeedbackClosedDays = 180;
        setup.CountStageDays = 90;
        setup.DeviceWorkStaleDays = 30;
        setup.DeviceFinishedJournalDays = 7;
        setup.DeviceOrderHistoryDays = 30;
        setup.DeviceOldWorkDays = 30;
    }
    return setup;
}

public void initValue()
{
    super();
    this.Enabled       = NoYes::Yes;
    this.DeviceCleanup = NoYes::Yes;
    this.PostQueueRegisteredDays = 90;
    this.PostQueueFailedDays = 180;
    this.SignInLogDays = 90;
    this.FeedbackClosedDays = 180;
    this.CountStageDays = 90;
    this.DeviceWorkStaleDays = 30;
    this.DeviceFinishedJournalDays = 7;
    this.DeviceOrderHistoryDays = 30;
    this.DeviceOldWorkDays = 30;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (this.PostQueueRegisteredDays < 0 || this.PostQueueFailedDays < 0 || this.SignInLogDays < 0 || this.FeedbackClosedDays < 0 || this.CountStageDays < 0 || this.DeviceWorkStaleDays < 0 || this.DeviceFinishedJournalDays < 0 || this.DeviceOrderHistoryDays < 0 || this.DeviceOldWorkDays < 0)
    {
        ret = checkFailed("Days can't be negative. 0 means never.");
    }
    return ret;
}
